using System.Linq.Expressions;using MongoDB.Bson;using MongoDB.Bson.Serialization;using MongoDB.Bson.Serialization.Serializers;using MongoDB.Driver;using ZosyalMedya.BuildingBlocks.Application.Persistence;using ZosyalMedya.BuildingBlocks.Domain;using ZosyalMedya.Modules.Comments.Application.Ports;using ZosyalMedya.Modules.Comments.Domain.Comments;
using SortDirection = ZosyalMedya.BuildingBlocks.Application.Persistence.SortDirection;
namespace ZosyalMedya.Modules.Comments.Infrastructure.Persistence.MongoDb;
public sealed class MongoCommentRepository:ICommentRepository{private static readonly object Gate=new();private readonly IMongoCollection<Comment>c;public MongoCommentRepository(IMongoDatabase db){Map();c=db.GetCollection<Comment>("comments");}public Task EnsureIndexesAsync(CancellationToken t)=>c.Indexes.CreateManyAsync([new(Builders<Comment>.IndexKeys.Ascending(x=>x.ContentId).Ascending(x=>x.Status).Ascending(x=>x.CreatedAtUtc),new CreateIndexOptions{Name="ix_thread"}),new(Builders<Comment>.IndexKeys.Ascending(x=>x.ParentId),new CreateIndexOptions{Name="ix_parent",Sparse=true})],t);public async Task<Comment?>SelectAsync(Expression<Func<Comment,bool>>predicate,CancellationToken cancellationToken=default){var x=await c.Find(predicate).Limit(2).ToListAsync(cancellationToken);return x.SingleOrDefault();}public async Task<IReadOnlyList<Comment>>ListByFilterAsync(Expression<Func<Comment,bool>>predicate,QueryOptions<Comment>?options=null,CancellationToken cancellationToken=default){options??=new();var find=c.Find(predicate);SortDefinition<Comment>sort=Builders<Comment>.Sort.Ascending(x=>x.Id);if(options.Sort is{Count:>0}){var d=options.Sort.Select(x=>x.Direction==SortDirection.Ascending?Builders<Comment>.Sort.Ascending(x.KeySelector):Builders<Comment>.Sort.Descending(x.KeySelector)).ToList();d.Add(Builders<Comment>.Sort.Ascending(x=>x.Id));sort=Builders<Comment>.Sort.Combine(d);}return await find.Sort(sort).Limit(options.BoundedLimit).ToListAsync(cancellationToken);}public async Task<IReadOnlyList<Comment>>ListPageAsync(CommentPageQuery query,CancellationToken cancellationToken=default){var f=Builders<Comment>.Filter.Eq(x=>x.ContentId,query.ContentId)&Builders<Comment>.Filter.Ne(x=>x.Status,CommentStatus.Moderated);if(query.CursorTime.HasValue&&query.CursorId.HasValue)f&=Builders<Comment>.Filter.Gt(x=>x.CreatedAtUtc,query.CursorTime.Value)|(Builders<Comment>.Filter.Eq(x=>x.CreatedAtUtc,query.CursorTime.Value)&Builders<Comment>.Filter.Gt(x=>x.Id,query.CursorId.Value));return await c.Find(f).Sort(Builders<Comment>.Sort.Ascending(x=>x.CreatedAtUtc).Ascending(x=>x.Id)).Limit(Math.Clamp(query.Limit,1,51)).ToListAsync(cancellationToken);}public async Task<CommentId>CreateAsync(Comment e,CancellationToken cancellationToken=default){try{await c.InsertOneAsync(e,cancellationToken:cancellationToken);return e.Id;}catch(MongoWriteException x)when(x.WriteError.Category==ServerErrorCategory.DuplicateKey){throw new PersistenceConflictException("comments.unique_conflict","Yorum zaten kayıtlıdır.",x);}}public async Task<bool>UpdateAsync(Expression<Func<Comment,bool>>predicate,Comment replacement,long?expectedVersion=null,CancellationToken cancellationToken=default){var f=Builders<Comment>.Filter.Where(predicate);if(expectedVersion.HasValue)f&=Builders<Comment>.Filter.Eq(x=>x.Version,expectedVersion);return(await c.ReplaceOneAsync(f,replacement,new ReplaceOptions(),cancellationToken)).ModifiedCount==1;}public async Task<long>DeleteByFilterAsync(Expression<Func<Comment,bool>>predicate,CancellationToken cancellationToken=default)=>(await c.DeleteManyAsync(predicate,cancellationToken)).DeletedCount;public Task<long>CountVisibleAsync(CommentedContentId contentId,CancellationToken cancellationToken=default)=>c.CountDocumentsAsync(x=>x.ContentId==contentId&&x.Status==CommentStatus.Visible,cancellationToken:cancellationToken);private static void Map(){lock(Gate){if(!BsonClassMap.IsClassMapRegistered(typeof(CommentId)))BsonClassMap.RegisterClassMap<CommentId>(m=>{m.AutoMap();m.MapCreator(x=>new CommentId(x.Value));m.MapMember(x=>x.Value).SetSerializer(new GuidSerializer(GuidRepresentation.Standard));});if(!BsonClassMap.IsClassMapRegistered(typeof(CommentAuthorId)))BsonClassMap.RegisterClassMap<CommentAuthorId>(m=>{m.AutoMap();m.MapCreator(x=>new CommentAuthorId(x.Value));m.MapMember(x=>x.Value).SetSerializer(new GuidSerializer(GuidRepresentation.Standard));});if(!BsonClassMap.IsClassMapRegistered(typeof(CommentedContentId)))BsonClassMap.RegisterClassMap<CommentedContentId>(m=>{m.AutoMap();m.MapCreator(x=>new CommentedContentId(x.Value));m.MapMember(x=>x.Value).SetSerializer(new GuidSerializer(GuidRepresentation.Standard));});if(!BsonClassMap.IsClassMapRegistered(typeof(AggregateRoot<CommentId>)))BsonClassMap.RegisterClassMap<AggregateRoot<CommentId>>(m=>{m.AutoMap();m.MapIdMember(x=>x.Id);m.UnmapMember(x=>x.DomainEvents);});if(!BsonClassMap.IsClassMapRegistered(typeof(Comment)))BsonClassMap.RegisterClassMap<Comment>(m=>m.AutoMap());}}}
